#!/usr/bin/env bash
# ==============================================================================
# run.sh - Universal One-Command Project Runner
# Generated by runrepo (https://github.com/Terrox0/runrepo)
# ==============================================================================
set -e

DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" >/dev/null 2>&1 && pwd)"
cd "$DIR"

# 1. Check for .env file
if [ ! -f .env ] && [ -f .env.example ]; then
  echo "[runrepo] Notice: .env not found. Initializing from .env.example..."
  cp .env.example .env
fi

# 2. Containerized run flag
if [ "$1" == "--container" ] || [ "$1" == "-c" ]; then
  echo "[runrepo] Booting in isolated Docker container (Port 8000)..."
  docker build -t runrepo-app .
  docker run -it --rm -p 8000:8000 -v "$(pwd):/app" runrepo-app
  exit 0
fi

# 3. Native host execution fast-path
echo "[runrepo] Checking native environment for python......"
if command -v python >/dev/null 2>&1; then
  echo "[runrepo] Launching natively: uvicorn main:app --reload --host 0.0.0.0 --port 8000"
  exec uvicorn main:app --reload --host 0.0.0.0 --port 8000
fi

# 4. Fallback to container if native toolchain is missing
if command -v docker >/dev/null 2>&1; then
  echo "[runrepo] Native python not found on PATH. Falling back to container..."
  docker build -t runrepo-app .
  docker run -it --rm -p 8000:8000 -v "$(pwd):/app" runrepo-app
else
  echo "[runrepo] Error: Neither native 'python' nor 'docker' is installed."
  echo "[runrepo] Please install 'python' or Docker Desktop to run this project."
  exit 1
fi
